mapper.select:
SELECT *
FROM doctor_register_appointment AS drat
LEFT JOIN hospital AS hos ON drat.hospital_id = hos.id
WHERE
    hos.province = #{location.province} 

        AND hos.city = #{location.city}


        AND hos.region = #{location.region}

    AND drat.department_id = #{departmentCode}

        AND drat.subject_id = #{SubjectCode}


        AND (DATE(drat.begin_date) = DATE(#{date}) OR   
        DATE(drat.end_date) = DATE(#{date}) OR          
        (drat.begin_date <= #{date} AND drat.end_date >= #{date}))
